    throw new StoreError('BAD_INPUT', 'bytes must be a Uint8Array');
  }
  const records = [];
  let offset = 0;
  let truncated = false;
  const decoder = new TextDecoder('utf-8', { fatal: true });

  while (true) {
    if (offset >= bytes.length) {
      break;
    }
    if (bytes.length - offset < HEADER_BYTES) {
      truncated = true;
      break;
    }
    const view = new DataView(bytes.buffer, bytes.byteOffset + offset, HEADER_BYTES);
    const length = view.getUint32(0, false);
    const crc = view.getUint32(4, false);
    const payloadStart = offset + HEADER_BYTES;
    const payloadEnd = payloadStart + length;
    if (payloadEnd > bytes.length) {
      truncated = true;
      break;
    }
    const payload = bytes.subarray(payloadStart, payloadEnd);
    if (crc32(payload) !== crc) {
      truncated = true;
      break;
    }
