    try {
      text = decoder.decode(payload);
    } catch {
      truncated = true;
      break;
    }
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      truncated = true;
      break;
    }
    if (!isRecord(parsed)) {
      truncated = true;
      break;
    }
