export class KvStore {
  #map = new Map();
  #chunks = [];
  #byteLength = 0;
  #recordCount = 0;

  /**
   * Append an already-encoded record to the log.
   *
   * @param {{t: string, k: string, v?: unknown}} record Record to append.
   */
  #appendRecord(record) {
    const frame = encodeRecord(record);
    this.#chunks.push(frame);
    this.#byteLength += frame.length;
    this.#recordCount += 1;
  }

  /** @returns {Uint8Array} The concatenated log bytes. */
  #concatChunks() {
    const result = new Uint8Array(this.#byteLength);
    let offset = 0;
