/**

diffs.newText:
 * @returns {{before: number, after: number, reclaimed: number}} Byte counts.
 */
compact() {
  const before = this.#byteLength;
  const entries = this.entries();
  this.#chunks = [];
  this.#byteLength = 0;
  this.#recordCount = 0;
  for (const [key, value] of entries) {
    this.#appendRecord({ t: 'put', k: key, v: value });
  }
  const after = this.#byteLength;
  return { before, after, reclaimed: before - after };
}

/** @returns {{version: number, entries: Array<[string, unknown]>}} Portable snapshot. */
snapshot() {
  return { version: 1, entries: this.entries() };
}

