/**

diffs.newText:
 * @returns {KvStore} Store holding the state of that prefix.
 */
static replay(bytes) {
  const decoded = decodeLog(bytes);
  const store = new KvStore();
  for (const record of decoded.records) {
    if (record.t === 'put') {
      store.#map.set(record.k, record.v);
    } else {
      store.#map.delete(record.k);
    }
  }
  store.#chunks = decoded.bytesUsed > 0 ? [bytes.slice(0, decoded.bytesUsed)] : [];
  store.#byteLength = decoded.bytesUsed;
  store.#recordCount = decoded.records.length;
  return store;
}

