diffs.newText:
   * @returns {KvStore} Store holding the snapshot state.
   */
  static fromSnapshot(snapshot) {
    if (typeof snapshot !== 'object' || snapshot === null) {
      throw new StoreError('BAD_SNAPSHOT', 'snapshot must be an object');
    }
    if (snapshot.version !== 1) {
      throw new StoreError('BAD_SNAPSHOT', 'unsupported snapshot version');
    }
    if (!Array.isArray(snapshot.entries)) {
      throw new StoreError('BAD_SNAPSHOT', 'snapshot entries must be an array');
    }
    const store = new KvStore();
    const seen = new Set();
    for (const entry of snapshot.entries) {
      if (!Array.isArray(entry) || entry.length !== 2) {
        throw new StoreError('BAD_SNAPSHOT', 'each snapshot entry must be a key and a value');
      }
      const [key, value] = entry;
      const validKey = checkKey(key);
      const validValue = checkValue(value);
      if (seen.has(validKey)) {
        throw new StoreError('BAD_SNAPSHOT', `duplicate key in snapshot: ${validKey}`);
      }
      seen.add(validKey);
      store.#map.set(validKey, validValue);
      store.#appendRecord({ t: 'put', k: validKey, v: validValue });
    }
    return store;
  }
}
